using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using System.Text.Json;using SonadaBeds.Web.Data;
namespace SonadaBeds.Web.Controllers;public class WishlistController(SonadaDbContext db):Controller{const string Key="sonada-wishlist";public async Task<IActionResult> Index(){var ids=Get();return View(await db.Products.Where(x=>ids.Contains(x.Id)).ToListAsync());}[HttpPost,ValidateAntiForgeryToken]public IActionResult Toggle(int id){var ids=Get();if(ids.Contains(id))ids.Remove(id);else ids.Add(id);HttpContext.Session.SetString(Key,JsonSerializer.Serialize(ids));return Redirect(Request.Headers.Referer.ToString().Length>0?Request.Headers.Referer.ToString():"/");}List<int> Get(){var s=HttpContext.Session.GetString(Key);return string.IsNullOrWhiteSpace(s)?[]:JsonSerializer.Deserialize<List<int>>(s)??[];}}
